<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Receipt</title></head><body style="font-family:Arial,sans-serif;color:#18302b"><h1>{{ config('app.name') }}</h1><h2>Receipt #{{ $sale->id }}</h2><p>Hello {{ $sale->customer_name ?? 'Customer' }},</p><p>Thank you for your purchase.</p><table cellpadding="10" style="border-collapse:collapse"><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr><tr><td>{{ $sale->product_name }}</td><td>{{ $sale->quantity }}</td><td>PHP {{ number_format($sale->unit_price,2) }}</td><td>PHP {{ number_format($sale->total_price,2) }}</td></tr></table><p>Sold by {{ $sale->staff_name }}<br>{{ $sale->created_at->format('M d, Y h:i A') }} ({{ config('app.timezone') }})</p></body></html>
